{
  "schemaVersion": 1,
  "task": 44,
  "mechanismId": "seoul.d16.war-contract.v1",
  "domainId": "D16",
  "title": "외교·전쟁·공성·포로 작동 계약과 공식 시트",
  "rulesVersion": "D16-CLOSURE-EVIDENCE-2026-10-08",
  "status": "approved-bounded-contract-with-held-required-inputs",
  "runtimeClaim": false,
  "canonAdopted": false,
  "authority": {
    "sealedRowsApplied": [
      {
        "row": "D06",
        "decisionId": "GP-13",
        "chosenOption": "A",
        "effect": "Treaty indivisible clauses, legal-effect events and physical handover events are distinct."
      },
      {
        "row": "D11",
        "decisionId": "T68-D16-ORGANIZATION-LIFECYCLE",
        "chosenOption": "A",
        "effect": "Organization persistence requires its registered representative, administrator and dissolution clauses; territorial loss or leader death alone never deletes it."
      },
      {
        "row": "D12",
        "decisionId": "T68-D17-PRICE-ACCEPTANCE",
        "chosenOption": "A",
        "effect": "Asset value, action cost and party acceptance remain separate; D16 never converts war score into price or consent."
      },
      {
        "row": "D17",
        "decisionId": "GP-07",
        "chosenOption": "B",
        "effect": "Missing title/extent/ratifier records are explicit proposals for later item approval, never active records."
      },
      {
        "row": "D18",
        "decisionId": "GP-11",
        "chosenOption": "A",
        "effect": "Command evaluation stores knowledge, authority and feasibility at decision time separately from later outcome."
      },
      {
        "row": "D22",
        "decisionId": "T68-NUMERIC-DESIGN-ASSUMPTIONS",
        "chosenOption": "B",
        "effect": "Normalize common units first; no new coefficient or formula is approved by this row."
      },
      {
        "row": "D24",
        "decisionId": "T68-COMBAT-THREE-DIMENSIONS",
        "chosenOption": "A",
        "effect": "Personal results aggregate through situation to unit channels with one casualty/loss ledger identity."
      },
      {
        "row": "D32",
        "decisionId": "GP-11",
        "chosenOption": "A",
        "effect": "Public Lite combat structure stays separate from Seoul real-time execution; combat numbers do not directly become war score."
      },
      {
        "row": "D37",
        "decisionId": "T68-NUMERIC-DESIGN-ASSUMPTIONS",
        "chosenOption": "A",
        "effect": "Approved body state is read-only and each derived effect is settled once; no health coefficient is invented."
      }
    ],
    "externalOwnerDecision": {
      "decisionId": "OWNER-REINFORCEMENT-20261004",
      "rule": "Any unit actually arriving while a battle is ongoing may join that battle.",
      "limits": [
        "No origin, rank, initial-roster or invented time-window restriction",
        "Arrival does not transfer command, enter a siege, process prisoners or add war score",
        "Arrival after battle end cannot enter that ended battle"
      ]
    },
    "priorAcceptedClauses": [
      "valid registered casus belli plus separate declaration authority",
      "fixed target, goal, beneficiary and terminal effects",
      "signed symmetric score bounded -100..100",
      "approved score events only with event/result deduplication",
      "exact endpoint forces only the still-valid casus belli effect",
      "occupation, legal right, ratification, settlement operation and restoration are separate ledgers",
      "below absolute 100 itemized peace proposals are allowed but never automatically accepted",
      "stable identity, explicit rules version and no silent migration"
    ],
    "noNewOwnerDecision": true,
    "rowIdsAreNotDomainIds": true
  },
  "separation": {
    "LORE": "Read-only authored country, title, office, person and place facts; this evidence pack creates none.",
    "GDD": "Bounded mechanism evidence for later canonical integration; mechanism-d16.json is intentionally deferred.",
    "runtime": "The validator is a documentary oracle, not product or gameplay implementation."
  },
  "quantifiedFieldUnits": {
    "scoreAttacker": "war-score point",
    "battleDelta": "war-score point",
    "battleChannelTotal": "war-score point",
    "arrivalAt": "D18 supplied world-clock coordinate",
    "battleEndedAt": "D18 supplied world-clock coordinate",
    "bodyRevision": "revision"
  },
  "stateMachines": {
    "war": [
      "proposed",
      "validated",
      "declared",
      "ongoing",
      "terminal-locked",
      "settled",
      "invalidated"
    ],
    "treaty": [
      "draft",
      "accepted",
      "signed",
      "legally-effective",
      "handover-pending",
      "fulfilled",
      "breached"
    ],
    "organization": [
      "active",
      "territory-lost",
      "representative-vacant",
      "administered",
      "dissolution-pending",
      "dissolved"
    ],
    "captivity": [
      "free",
      "capture-reported",
      "transporting",
      "detained",
      "release-pending",
      "released",
      "dead"
    ]
  },
  "requiredHeldInputs": [
    "occupation denominator, weights, cadence, fractional policy, target-control tick and recovery/reset formula",
    "siege stages, duration, supply, breach, assault loss, surrender, repair and interruption numerics",
    "concrete casus belli catalog, costs, truce lengths, reparations and country/title records",
    "captivity release, recapture, escape, ransom and multiwar subscriber transitions",
    "prisoner/peace item prices, acceptance, repricing, reservation, signature and breach rules",
    "same-boundary total order for death, invalidation, acceptance and exact endpoint",
    "organization-specific representative, administrator and dissolution records",
    "reinforcement spawn/entry geometry, initial stance and command reassignment",
    "health/fatigue coefficients and combat-to-score conversion beyond approved discrete score events"
  ],
  "sourceClaims": {
    "CK3": "Comparison evidence only; version and formula conflicts remain bounded and no source literal is adopted.",
    "Norland": "Comparison evidence only; does not provide Seoul continuous war score, casus belli registration or atomic custody policy.",
    "GURPS_LIKE": "Lite combat structure may inform D15 only; it supplies no D16 war-score, siege, treaty or prisoner formula."
  },
  "integrationDeferral": {
    "status": "explicit-deferred-to-separate-wave",
    "items": [
      "GDD/canon/locales/ko-KR/system-design/mechanism-d16.json",
      "GDD collection registration",
      "rendered lock",
      "product TOOL mechanism validator integration",
      "canonical commits"
    ],
    "reason": "User explicitly scoped this task to ignored evidence pack only."
  },
  "domainClosure": {
    "ready": false,
    "verdict": "FAIL_REQUIRED_INPUTS_HELD",
    "reason": "Sealed choices approve authoring and separation directions, not the exact required occupation, siege, custody, pricing, truce, country/title and event-order records. This pack closes the approved bounded invariants without inventing those values."
  },
  "sourceEvidenceStatus": "approved-bounded-contract-with-held-required-inputs",
  "decisionDisposition": [
    {
